<?php
require_once __DIR__.'/includes/permissions.php'; require_login();
$page_title='Comunicar problema'; $productId=safe_int($_POST['product_id']??$_GET['produto']??0); $orderId=safe_int($_POST['order_id']??$_GET['pedido']??0); $error=null;
// Confirma que o produto existe e que o pedido é visível para quem denuncia (comprador: o seu pedido; agricultor: pedido com itens seus).
$product=null;if($productId>0){$s=db()->prepare('SELECT id,name FROM products WHERE id=?');$s->execute([$productId]);$product=$s->fetch()?:null;}
$order=null;if($orderId>0){$role=user()['role'];if($role==='buyer'){$s=db()->prepare('SELECT id,order_number FROM orders WHERE id=? AND buyer_id=?');$s->execute([$orderId,(int)user()['buyer_id']]);}elseif($role==='farmer'){$s=db()->prepare('SELECT DISTINCT o.id,o.order_number FROM orders o JOIN order_items oi ON oi.order_id=o.id WHERE o.id=? AND oi.farmer_id=?');$s->execute([$orderId,(int)user()['farmer_id']]);}else{$s=db()->prepare('SELECT id,order_number FROM orders WHERE id=?');$s->execute([$orderId]);}$order=$s->fetch()?:null;}
$back=$product?base_path('produto.php?id='.$product['id']):($order?base_path(user()['role']==='buyer'?'comprador/pedido-detalhes.php?id='.$order['id']:(user()['role']==='farmer'?'agricultor/pedido-detalhes.php?id='.$order['id']:'admin/pedidos.php')):base_path('index.php'));
if(is_post()){verify_csrf($_POST['csrf']??'');$subject=trim((string)($_POST['subject']??''));$description=trim((string)($_POST['description']??''));
  if($productId>0&&!$product)$error='O produto indicado não existe.';
  elseif($orderId>0&&!$order)$error='O pedido indicado não foi encontrado na sua conta.';
  elseif(mb_strlen($subject)<5||mb_strlen($subject)>160||mb_strlen($description)<15||mb_strlen($description)>5000)$error='Indique um assunto (5 a 160 caracteres) e uma descrição com pelo menos 15 caracteres.';
  else{$s=db()->prepare('INSERT INTO complaints(reporter_id,product_id,order_id,subject,description) VALUES(?,?,?,?,?)');$s->execute([current_user_id(),$product?(int)$product['id']:null,$order?(int)$order['id']:null,$subject,$description]);audit(current_user_id(),'create','complaints','Utilizador criou a denúncia #'.db()->lastInsertId());flash('success','A sua denúncia foi enviada para análise.');redirect($back);}}
include __DIR__.'/includes/header.php';
?><section class="container py-5"><div class="auth-card mx-auto"><span class="eyebrow">Apoio e segurança</span><h1 class="mt-2">Comunicar um problema</h1><p class="text-muted">Descreva a situação. O SuperAdmin irá analisar o caso.</p><?php if($product): ?><p class="small mb-2"><i class="bi bi-box-seam me-1"></i>Produto: <strong><?=e($product['name'])?></strong></p><?php endif; ?><?php if($order): ?><p class="small mb-2"><i class="bi bi-receipt me-1"></i>Pedido: <strong><?=e($order['order_number'])?></strong></p><?php endif; ?><?php if(($productId>0&&!$product)||($orderId>0&&!$order)): ?><div class="alert alert-warning small">A referência indicada não foi encontrada; a denúncia será registada sem ela.</div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><form method="post"><?=csrf_field()?><input type="hidden" name="product_id" value="<?=$product?(int)$product['id']:0?>"><input type="hidden" name="order_id" value="<?=$order?(int)$order['id']:0?>"><div class="mb-3"><label class="form-label" for="subject">Assunto</label><input id="subject" name="subject" class="form-control" minlength="5" maxlength="160" value="<?=e($_POST['subject']??'')?>" required></div><div class="mb-4"><label class="form-label" for="description">Descrição</label><textarea id="description" name="description" class="form-control" rows="6" minlength="15" maxlength="5000" required><?=e($_POST['description']??'')?></textarea></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="<?=e($back)?>">Voltar</a><button class="btn btn-primary flex-grow-1">Enviar denúncia <i class="bi bi-flag ms-2"></i></button></div></form></div></section><?php include __DIR__.'/includes/footer.php'; ?>
